FictionBook.stylesheet:
 body  { font-family: serif; line-height: 1.6; }
.highlight  { background: #ffffaa; }
.dropcap    { font-size: 3em; float: left; line-height: 1; }
.custom-class { font-variant: small-caps; color: #336699; }
